import lens

TARGET = "compact_json"
DEPTH = 2

resp = lens.callees(TARGET, transitive=True, depth=DEPTH)
nodes = resp.get("nodes", [])

candidates = {}
for n in nodes:
    name = n.get("name")
    file = n.get("file", "")
    if name == TARGET or not file.startswith("src/store/"):
        continue
    candidates[name] = file

def sig_line(text, name):
    for line in text.splitlines():
        if f"fn {name}(" in line:
            return line
    return ""

skel_cache = {}
returns_option = []
for name, file in candidates.items():
    if file not in skel_cache:
        sk = lens.skeleton(file)
        skel_cache[file] = sk.get("skeleton", "") if isinstance(sk, dict) else str(sk)
    if "-> Option<" in sig_line(skel_cache[file], name):
        returns_option.append(name)

returns_option.sort()
print(f"target=compact_json transitive_callees={len(candidates)} returns_option={len(returns_option)}")
print(",".join(returns_option))
